fn inl_vi_RunCamera_unfused<'a>(
    ctx: &'a Ctx,
    gobj: HSD_GObj<'a>,
    erase_color: _GXColor<'a>,
    prio: u64,
) {
    let mut gobj = gobj;
    let mut erase_color = erase_color;
    let mut prio = prio;
    let mut cobj: HSD_CObj<'a> =
        (Handle::cast::<HSD_CObj<'a>>(inl_HSD_GObjGetHSDObj_unfused(ctx, gobj)));
    if (fns::HSD_CObjSetCurrent(ctx, cobj) != 0) {
        fns::HSD_SetEraseColor(
            ctx,
            (erase_color).r(),
            (erase_color).g(),
            (erase_color).b(),
            (erase_color).a(),
        );
        fns::HSD_CObjEraseScreen(
            ctx,
            (Handle::cast::<HSD_CObj<'a>>(inl_HSD_GObjGetHSDObj_unfused(ctx, gobj))),
            1_i32,
            0_i32,
            1_i32,
        );
        fns::vi_8031CA04(ctx, gobj);
        (gobj).set_gxlink_prios(prio);
        fns::HSD_GObj_80390ED0(ctx, gobj, (7_i32 as u32));
        fns::HSD_CObjEndCurrent(ctx);
    }
}

